-- mod-atlas: the generated-map pool (DESIGN 6.2 spike). Generated by tools/clones/gen_sql.py from pool.json
-- and the client's own Map.dbc / MapDifficulty.dbc / AreaTable.dbc, the same rows as
-- client_patch/patch-T.MPQ.
-- Do not edit by hand: change tools/clones/pool.json and regenerate both.
--
-- Pool maps (950-999) have no terrain, vmaps or mmaps. mod-atlas places kit pieces in them as gameobjects
-- (type 14, a stock WMO with a stock display: the server has its collision model). Each pool map's zone is
-- its own area (7900-7949), so client and server leave the zone the player came from.
-- Inert until used (.atlas spike, opted-in accounts). Uninstall: data/sql/uninstall/atlas_pool_uninstall.sql.

DELETE FROM `instance_template` WHERE `map` BETWEEN 950 AND 999;
DELETE FROM `mapdifficulty_dbc` WHERE `MapID` BETWEEN 950 AND 999;
DELETE FROM `map_dbc` WHERE `ID` BETWEEN 950 AND 999;
DELETE FROM `mapdifficulty_dbc` WHERE `ID` = 759;
DELETE FROM `areatable_dbc` WHERE `ID` BETWEEN 7900 AND 7949;

